    ("ci.effect_status", "Đơn chuyển \"Đang ở\", buồng {room} chuyển \"Có khách, sạch\".", "Booking becomes \"In house\", room {room} becomes \"Occupied, clean\".", None, "13-check-in.html"),
    ("ci.effects_title", "Khi bấm Nhận phòng", "When you tap Check in", None, "13-check-in.html"),
